(function(){document.addEventListener('submit',event=>{const form=event.target.closest('[data-local-form]');if(!form)return;event.preventDefault();if(!form.reportValidity())return;const status=form.querySelector('[data-form-status]');if(status)status.textContent='Your message is ready, but it has not been sent because this frontend is not connected to an inbox yet.';form.querySelector('[type="submit"]').disabled=true;});})();
